<?php

namespace App\Support;

/**
 * The built-in wording, generated by tools/i18n-build.mjs into i18n/catalog.json:
 *   { site: { keys: {key: {en, ar, where}}, phrases: {en: {ar, where}} }, admin: { phrases: {en: ar} } }
 * Admin edits live in the `translations` table and win over this file.
 */
class I18nCatalog
{
    private static ?array $cache = null;

    public static function path(): string
    {
        return config('store.root').'/i18n/catalog.json';
    }

    public static function load(): array
    {
        if (self::$cache !== null) {
            return self::$cache;
        }
        $p = self::path();
        $data = is_file($p) ? json_decode((string) file_get_contents($p), true) : null;

        return self::$cache = is_array($data) ? $data + ['site' => [], 'admin' => []] : ['site' => ['keys' => [], 'phrases' => []], 'admin' => ['phrases' => []]];
    }

    public static function reset(): void
    {
        self::$cache = null;
    }

    public static function hash(string $source): string
    {
        return sha1($source);
    }

    /**
     * Every built-in entry of a scope, keyed by hash:
     *   [hash => [source, key|null, en, ar, where]]
     */
    public static function entries(string $scope): array
    {
        $c = self::load();
        $out = [];
        if ($scope === 'site') {
            foreach ($c['site']['keys'] ?? [] as $key => $v) {
                $out[self::hash($key)] = ['source' => $key, 'key' => $key, 'en' => (string) ($v['en'] ?? ''), 'ar' => (string) ($v['ar'] ?? ''), 'where' => (string) ($v['where'] ?? '')];
            }
            foreach ($c['site']['phrases'] ?? [] as $en => $v) {
                $out[self::hash($en)] = ['source' => $en, 'key' => null, 'en' => $en, 'ar' => (string) (is_array($v) ? ($v['ar'] ?? '') : $v), 'where' => (string) (is_array($v) ? ($v['where'] ?? '') : '')];
            }
        } else {
            foreach ($c['admin']['phrases'] ?? [] as $en => $ar) {
                $out[self::hash($en)] = ['source' => $en, 'key' => null, 'en' => $en, 'ar' => (string) $ar, 'where' => 'admin'];
            }
        }

        return $out;
    }
}
